<?php
add_action('after_setup_theme',function(){load_theme_textdomain('rzzlaw',get_template_directory().'/languages');add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('responsive-embeds');add_theme_support('align-wide');add_theme_support('custom-logo',['height'=>80,'width'=>280,'flex-width'=>true,'flex-height'=>true]);add_theme_support('html5',['search-form','gallery','caption','style','script']);register_nav_menus(['primary'=>'Primary navigation','footer'=>'Footer navigation']);add_image_size('rzz-portrait',650,800,true);});
add_action('wp_enqueue_scripts',function(){
$files=['base','header','footer','cookies','contact','map'];
if(is_front_page())$files=array_merge($files,['hero','expertise','why-us','team','voices','faq']);
elseif(is_post_type_archive('expertise')||is_singular('expertise'))$files=array_merge($files,['expertise','service','related-expertise']);
elseif(is_post_type_archive('team')||is_singular('team'))$files=array_merge($files,['team','profile']);
elseif(is_page('about'))$files=array_merge($files,['about','story','about-guides','about-practice','about-philosophy']);elseif(is_page('contact'))$files[]='contact-page';elseif(is_page('careers'))$files[]='careers';else $files[]='editorial';
if(is_post_type_archive(['expertise','team'])||is_singular(['expertise','team','post']))$files=array_merge($files,['about','about-guides','about-practice','about-philosophy','principles-band']);
foreach(array_unique($files) as $file)wp_enqueue_style('rzz-'.$file,rzz_asset('css/'.$file.'.css'),[],filemtime(get_template_directory().'/assets/css/'.$file.'.css'));
foreach(['main','consent'] as $script)wp_enqueue_script('rzz-'.$script,rzz_asset('js/'.$script.'.js'),[],filemtime(get_template_directory().'/assets/js/'.$script.'.js'),['in_footer'=>true,'strategy'=>'defer']);
});
function rzz_fallback_menu(){echo '<ul class="nav-list">';foreach([''=>'Home','about'=>'About','team'=>'Team','expertise'=>'Expertise','insights'=>'Insights','careers'=>'Careers','contact'=>'Contact'] as $slug=>$label){$active=($slug===''&&is_front_page())||($slug&&(is_page($slug)||is_post_type_archive($slug)||is_singular($slug)));echo '<li'.($slug==='expertise'?' class="has-submenu"':'').'><a '.($active?'aria-current="page" ':'').'href="'.esc_url(rzz_link($slug)).'">'.esc_html($label).'</a>';if($slug==='expertise'){echo '<button class="submenu-toggle" aria-label="Show expertise areas" aria-expanded="false">'.rzz_ui_icon('chevron').'</button><ul class="sub-menu">';foreach(get_posts(['post_type'=>'expertise','numberposts'=>-1,'orderby'=>'menu_order','order'=>'ASC']) as $item)echo '<li><a href="'.esc_url(get_permalink($item)).'">'.esc_html($item->post_title).'</a></li>';echo '</ul>';}echo '</li>';}echo '</ul>';}
add_action('wp_head',function(){echo '<link rel="preload" href="'.esc_url(rzz_asset('fonts/soehne-breit-web-buch_1c0cea3d.woff2')).'" as="font" type="font/woff2" crossorigin>';if(!has_site_icon())echo '<link rel="icon" type="image/svg+xml" href="'.esc_url(rzz_asset('images/favicon.svg')).'">';},1);
